sp_widget.script:
(function() {
    data.questions = [];
    data.sectionId = $sp.getParameter("section_id") || "";
    data.msg = "";
    try {
        if (!data.sectionId) return;
        if (input && input.action === "add_question") {
            var qGr = new GlideRecord("x_1433041_identi_0_question");
            qGr.initialize();
            qGr.setValue("section", data.sectionId);
            qGr.setValue("question_key", (input.label || "question").toLowerCase().replace(/[^a-z0-9]+/g, "_") + "_" + new GlideDateTime().getNumericValue());
            qGr.setValue("label", input.label || "New Question");
            qGr.setValue("question_type", input.question_type || "single_line_text");
            qGr.setValue("required", input.required || false);
            qGr.setValue("order", input.order_num || 100);
            qGr.setValue("active", true);
            if (input.help_text) qGr.setValue("help_text", input.help_text);
            if (input.placeholder) qGr.setValue("placeholder", input.placeholder);
            if (input.default_value) qGr.setValue("default_value", input.default_value);
            qGr.insert();
            data.msg = "Question added.";
            return;
        }
        if (input && input.action === "update_question") {
            var uGr = new GlideRecord("x_1433041_identi_0_question");
            if (input.question_id && uGr.get(input.question_id)) {
                if (input.label) uGr.setValue("label", input.label);
                if (input.question_type) uGr.setValue("question_type", input.question_type);
                if (typeof input.required !== "undefined") uGr.setValue("required", input.required);
                if (input.order_num) uGr.setValue("order", input.order_num);
                if (input.help_text !== undefined) uGr.setValue("help_text", input.help_text);
                if (input.placeholder !== undefined) uGr.setValue("placeholder", input.placeholder);
                uGr.update();
                data.msg = "Question updated.";
            }
            return;
        }
        if (input && input.action === "delete_question") {
            var dGr = new GlideRecord("x_1433041_identi_0_question");
            if (input.question_id && dGr.get(input.question_id)) {
                dGr.setValue("active", false);
                dGr.update();
                data.msg = "Question removed.";
            }
            return;
        }
        // Load questions for this section
        var gr = new GlideRecord("x_1433041_identi_0_question");
        gr.addQuery("section", data.sectionId);
        gr.addQuery("active", true);
        gr.orderBy("order");
        gr.setLimit(100);
        gr.query();
        while (gr.next()) {
            data.questions.push({
                sys_id: gr.getValue("sys_id"),
                label: gr.getValue("label"),
                question_key: gr.getValue("question_key"),
                question_type: gr.getDisplayValue("question_type"),
                question_type_value: gr.getValue("question_type"),
                required: gr.getValue("required") === "1",
                order: gr.getValue("order"),
                help_text: gr.getValue("help_text") || "",
                placeholder: gr.getValue("placeholder") || ""
            });
        }
    } catch (e) {
        gs.error("IBAR Question Form widget error: " + e.message);
    }
})();
